const EKEFALL_RECIPES = [{"id":"ekefall-bok1-01","name":"Mc’Chicken","category":"Lunch","servings":1,"kcal":550,"protein":38,"carbs":55,"fat":18,"estimated":false,"ingredientItems":[{"name":"Kycklingfärs","amount":150.0,"unit":"g"},{"name":"Hamburgarbröd (1 st)","amount":70.0,"unit":"g"},{"name":"Cornflakes","amount":20.0,"unit":"g"},{"name":"Gul senap (1 tsk)","amount":5.0,"unit":"g"},{"name":"Lättmajo (4 tsk); Isbergssallad (så mycket du vill) Kryddor; Paprikapulver, lökpulver,; salt & peppar (chili flakes om du; vill ha hetta)","amount":20.0,"unit":"g"}],"ingredients":"150g Kycklingfärs\n  70g Hamburgarbröd (1 st)\n       20g Cornflakes\n     5g Gul senap (1 tsk)\n    20g Lättmajo (4 tsk)\n          Isbergssallad\n        (så mycket du vill)\n\n\n           Kryddor\n   Paprikapulver, lökpulver,\nsalt & peppar (chili flakes om du\n             vill ha hetta)","instructions":"1. Bland ihop kycklingfärs, gul senap\n (yellow mustard, finns att köpa på\n         Ica) & dina kryddor.\n 2. Häv ner cornflakes  i en plastpåse\n       och krossa ordentligt.\n       3. Blöt dina händer något\n         (blir mindre kladdigt)\n  4. Forma färsen till bollar & tryck\n        ner  i dina cornflakes.\n 5. In  i ugnen på en plåt  i 20 minuter\n   på 200 grader, efter halva tiden\n  vänder du på burgarna (tiden kan\n   variera något beroende på ugn),\n   fungerar utmärkt med airfryer!\n  6. Sätt ihop din burgare och njut!","image":"./ekefall-photos/ekefall-bok1-01.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-02","name":"Kebabpizza på libabröd","category":"Middag","servings":1,"kcal":550,"protein":36,"carbs":58,"fat":20,"estimated":false,"ingredientItems":[{"name":"Kycklingkebab","amount":100.0,"unit":"g"},{"name":"Libabröd (1 st)","amount":85.0,"unit":"g"},{"name":"Pizzasås (mutti)","amount":50.0,"unit":"g"},{"name":"Mager ost (ca 12%)","amount":30.0,"unit":"g"},{"name":"Rödlök (ok att ta extra)","amount":20.0,"unit":"g"},{"name":"Het kebabsås (Schysstkäk); Fefferoni (om du vill) Grönsaker är alltid ok att; skippa eller ta extra av.","amount":20.0,"unit":"g"}],"ingredients":"100g Kycklingkebab\n    85g Libabröd (1 st)\n    50g Pizzasås (mutti)\n  30g Mager ost (ca 12%)\n20g Rödlök (ok att ta extra)\n     20g Het kebabsås\n       (Schysstkäk)\n     Fefferoni (om du vill)\n\n\n  Grönsaker är alltid ok att\n   skippa eller ta extra av.","instructions":"1. Sätt ugnen på 200 grader.\n 2. Fram med ditt libabröd, på med\n        tomatsås och ost.\n3. In  i ugnen ca 10 minuter (tills du\n       är klar med kebaben)\n 4. Stek kycklingkebab och lägg på\n      pizzan när den är klar.\n 5. Servera pizzan toppad med mild\n       kebabsås & rödlök!","image":"./ekefall-photos/ekefall-bok1-02.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-05","name":"Kycklinggratäng","category":"Lunch","servings":1,"kcal":550,"protein":39,"carbs":54,"fat":22,"estimated":false,"ingredientItems":[{"name":"Olivolja (1 tsk)","amount":5.0,"unit":"g"},{"name":"Kycklingbröstfilé","amount":100.0,"unit":"g"},{"name":"Pasta, okokt (1dl=ca 35g)","amount":60.0,"unit":"g"},{"name":"Mager ost (ca 12% fett)","amount":30.0,"unit":"g"},{"name":"Lätt creme fraiche (smak av paprika % chili)","amount":100.0,"unit":"g"}],"ingredients":"5g Olivolja (1 tsk)\n   100g Kycklingbröstfilé\n60g Pasta, okokt (1dl=ca 35g)\n 30g Mager ost (ca 12% fett)\n   100g Lätt creme fraiche\n  (smak av paprika % chili)","instructions":"1. Koka pasta.\n   2. Skär din kyckling  i mindre bitar,\n       stek  i olja och krydda med\n)     paprikapulver, grillkrydda,\n               salt & peppar.\n  3. I med smaksatt creme fraiche, jag\n tog den med smak av paprika & chili.\n    4. Ta fram en form och häv  i din\n      kokta pasta, kyckling och\n            toppa med ost.\n    5. In  i ugnen på 200 grader ca 15\n    minuter, tills osten fått fin yta.\n       6. Servera gärna med valfria\n              grönsaker!","image":"./ekefall-photos/ekefall-bok1-05.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-07","name":"Potatis i ugn med schnitzel","category":"Lunch","servings":1,"kcal":550,"protein":38,"carbs":61,"fat":20,"estimated":false,"ingredientItems":[{"name":"Olivolja (1 msk)","amount":15.0,"unit":"g"},{"name":"Kycklingbröstfilé","amount":145.0,"unit":"g"},{"name":"Potatis","amount":200.0,"unit":"g"},{"name":"Panko (2 msk)","amount":14.0,"unit":"g"},{"name":"Vetemjöl (1 msk)","amount":9.0,"unit":"g"},{"name":"(att vända i)","amount":1.0,"unit":"ägg"},{"name":"Sparris (ca 20g st)","amount":80.0,"unit":"g"},{"name":"Rödvinssås (1/2 dl)","amount":50.0,"unit":"g"}],"ingredients":"15g Olivolja (1 msk)\n145g Kycklingbröstfilé\n     200g Potatis\n  14g Panko (2 msk)\n 9g Vetemjöl (1 msk)\n  1 ägg (att vända i)\n80g Sparris (ca 20g st)\n50g Rödvinssås (1/2 dl)","instructions":"1. Börja med att koka din potatis,\n     smasha sen med ett glas.\n2. Ringla över hälften av oljan, sätt\n    in  i ugnen på 200 grader  i ca\n   30-45 min (kolla av efter 30)\n    3. Banka ut din kycklingfile.\n          4. Salta & peppra.\n  5. Vänd sen  i mjöl, ägg & panko\n       6. Stek  i resten av oljan.\n       7. Värm din rödvinssås.\n  8. Servera med sparris och njut!!","image":"./ekefall-photos/ekefall-bok1-07.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-08","name":"Kycklingkebabgryta","category":"Middag","servings":1,"kcal":550,"protein":40,"carbs":57,"fat":19,"estimated":false,"ingredientItems":[{"name":"Kycklingkebab","amount":140.0,"unit":"g"},{"name":"Ris, okokt (1dl ca 80g)","amount":55.0,"unit":"g"},{"name":"Lätt Crème Fraiche,; Paprika & Chili","amount":100.0,"unit":"g"},{"name":"Grekisk yoghurt, 0% fett; Persilja (så mycket/lite du vill)","amount":50.0,"unit":"g"}],"ingredients":"140g Kycklingkebab\n 55g Ris, okokt (1dl ca 80g)\n  100g Lätt Crème Fraiche,\n      Paprika & Chili\n50g Grekisk yoghurt, 0% fett\n\n\n           Persilja\n    (så mycket/lite du vill)","instructions":"1. Koka ris\n 2. Stek kycklingkebab (jag gillar\n    steka kebaben ganska hårt)\n      3. I med creme fraichen.\n4. Grekisk yoghurt kan du ta  i som\n sista grej (får ej koka), eller äta\n              bredvid!\n5. Servera med ris och toppa gärna\n       med färsk persilja.","image":"./ekefall-photos/ekefall-bok1-08.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-09","name":"Flygande Jacob","category":"Lunch","servings":1,"kcal":550,"protein":36,"carbs":55,"fat":21,"estimated":false,"ingredientItems":[{"name":"Olja (1 tsk)","amount":5.0,"unit":"g"},{"name":"Kycklingbröstfilé","amount":115.0,"unit":"g"},{"name":"Ris, okokt (1dl ca 80g)","amount":50.0,"unit":"g"},{"name":"Mini fraiche (5% fett)","amount":75.0,"unit":"g"},{"name":"Grädde (4% fett)","amount":75.0,"unit":"g"},{"name":"Sweet chilisås (1 msk)","amount":15.0,"unit":"g"},{"name":"Bacon; Toppa med lite banan om du vill!","amount":30.0,"unit":"g"}],"ingredients":"5g Olja (1 tsk)\n  115g Kycklingbröstfilé\n50g Ris, okokt (1dl ca 80g)\n 75g Mini fraiche (5% fett)\n   75g Grädde (4% fett)\n 15g Sweet chilisås (1 msk)\n        30g Bacon\n\n\n  Toppa med lite banan\n       om du vill!","instructions":"1. Koka ris.\n  2. Stek kyckling  i olja och krydda\nmed paprikapulver, (cayennepeppar),\n     grillgrydda, salt & peppar.\n 3. Blanda ihop mini creme fraiche,\n  lättgrädde, sweetchilisås, sambal\n        oelek, salt & peppar.\n   4. Lägg riset  i en form, på med\n    kyckling och häll över såsen.\n     5. In  i ugnen på 200 grader\n                        i 15-20 min.\n         6. Toppa sen med din\n        knaperstekta bacon\n  7. Servera med valfria grönsaker!","image":"./ekefall-photos/ekefall-bok1-09.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-10","name":"Tortilla Calzone","category":"Middag","servings":1,"kcal":550,"protein":46,"carbs":47,"fat":19,"estimated":false,"ingredientItems":[{"name":"Kycklingpålägg","amount":80.0,"unit":"g"},{"name":"Ost (runt 17% fett)","amount":80.0,"unit":"g"},{"name":"Tortillabröd (2 st)","amount":80.0,"unit":"g"},{"name":"Pizzasås, mutti; Oregano","amount":50.0,"unit":"g"}],"ingredients":"80g Kycklingpålägg\n80g Ost (runt 17% fett)\n 80g Tortillabröd (2 st)\n  50g Pizzasås, mutti\n       Oregano","instructions":"1. Ta fram två (medium) tortillabröd.\n     2. På med pizzasås på halva.\n    3. Sen på med kycklingpålägg,\n           ost och oregano.\n  4. Vik ihop och tryck till kanterna\n  med en gaffel innan du sätter in\n         i ugn/airfryer ca 10 minuter\n           på 200 grader.","image":"./ekefall-photos/ekefall-bok1-10.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-11","name":"Krämig kyckling med ris","category":"Lunch","servings":1,"kcal":550,"protein":38,"carbs":55,"fat":20,"estimated":false,"ingredientItems":[{"name":"Olja (1 tsk)","amount":5.0,"unit":"g"},{"name":"Kycklingbröstfilé","amount":130.0,"unit":"g"},{"name":"Ris, okokt (1dl ca 80g); 1-2 Vitlöksklyftor","amount":60.0,"unit":"g"},{"name":"Tomatpuré (1 msk)","amount":15.0,"unit":"g"},{"name":"Grädde, 10-15%","amount":75.0,"unit":"g"},{"name":"Parmesan (2 msk); En näve spenat (så mycket/lite du vill)","amount":16.0,"unit":"g"}],"ingredients":"5g Olja (1 tsk)\n  130g Kycklingbröstfilé\n60g Ris, okokt (1dl ca 80g)\n    1-2 Vitlöksklyftor\n  15g Tomatpuré (1 msk)\n   75g Grädde, 10-15%\n  16g Parmesan (2 msk)\n     En näve spenat\n  (så mycket/lite du vill)","instructions":"1. Koka ris.\n 2. Skär din kycklingfile på hälften.\n    3. Krydda med paprikapulver,\n  chiliflakes (skippa om du ej gillar\n   hetta), persilja, salt & peppar.\n  4. Stek kycklingen  i olja tills den\n fått fin yta, sätt åt sidan sen steker\n   du vitlök, tillsätt tomatpure &\nsamma kryddor som till kycklingen.\n 5. Häll  i grädde & riv ner parmesan\n(ha låg värme på plattan). Sist  i med\n       spenat & din kyckling.\n6. Låt gotta sig någon minut, servera\n        med ris och njut!","image":"./ekefall-photos/ekefall-bok1-11.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-13","name":"Kyckling med champinjonsås","category":"Lunch","servings":1,"kcal":550,"protein":39,"carbs":57,"fat":19,"estimated":false,"ingredientItems":[{"name":"Olja (1 tsk)","amount":5.0,"unit":"g"},{"name":"Kycklingbröstfilé","amount":130.0,"unit":"g"},{"name":"Potatis","amount":225.0,"unit":"g"},{"name":"lök; 1-2 vitlöksklyftor","amount":30.0,"unit":"g"},{"name":"champinjoner","amount":100.0,"unit":"g"},{"name":"Grädde, 10-15% (1 dl)","amount":100.0,"unit":"g"},{"name":"Mjölk, (1 dl)","amount":100.0,"unit":"g"},{"name":"Sparris (ca 20g st); Persilja (1-2 tsk) (Kan behövas lite mjöl för; att göra såsen tjockare)","amount":80.0,"unit":"g"}],"ingredients":"5g Olja (1 tsk)\n  130g Kycklingbröstfilé\n       225g Potatis\n         30g lök\n     1-2 vitlöksklyftor\n    100g champinjoner\n100g Grädde, 10-15% (1 dl)\n    100g Mjölk, (1 dl)\n  80g Sparris (ca 20g st)\n      Persilja (1-2 tsk)\n(Kan behövas lite mjöl för\n  att göra såsen tjockare)","instructions":"1. Koka upp potatis.\n      2. Skär din kycklingfile på\n       hälften/tunnare skivor.\n    3. Krydda med paprikapulver,\n  vitlökspulver, italienska kryddor\n   (oregano, basilka,timjan osv),\n     chiliflakes, salt & peppar.\n  4. Stek  i olja tills de fått fin yta.\n            5. Sätt åt sidan.\n6. Stek lök, vitlök & champinjoner.\n    7. Häll  i grädde och persilja.\n8. Mosa din potatis,  i med lite mjölk\n            i taget. Salta & peppra\n   9. Servera med sparris och njut!","image":"./ekefall-photos/ekefall-bok1-13.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-14","name":"Kebabpasta med ostsås","category":"Middag","servings":1,"kcal":550,"protein":43,"carbs":54,"fat":19,"estimated":false,"ingredientItems":[{"name":"Kycklingkebab","amount":100.0,"unit":"g"},{"name":"Pasta (1 dl ca 35g)","amount":50.0,"unit":"g"},{"name":"Vetemjöl (1 msk)","amount":9.0,"unit":"g"},{"name":"Smör (1 tsk)","amount":5.0,"unit":"g"},{"name":"Mjölk (1 dl)","amount":100.0,"unit":"g"},{"name":"Ost (Runt 15% fett)","amount":50.0,"unit":"g"}],"ingredients":"100g Kycklingkebab\n50g Pasta (1 dl ca 35g)\n  9g Vetemjöl (1 msk)\n    5g Smör (1 tsk)\n   100g Mjölk (1 dl)\n50g Ost (Runt 15% fett)","instructions":"1. Koka pasta.\n      2. Stek kycklingkebab.\n    3. Smält smör & ha  i mjöl.\n   4. Häll  i mjölk och rör runt\n           tills de tjocknat,\n5. Sänk värmen och tillsätt osten.\n    (Om det bli för tjockt,\n            i med lite mer mjölk)\n       6. Servera pastan med\n    kycklingkebaben och häll\n         över din ostsås!","image":"./ekefall-photos/ekefall-bok1-14.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-16","name":"Mango Chutney gratäng","category":"Middag","servings":1,"kcal":550,"protein":37,"carbs":65,"fat":16,"estimated":false,"ingredientItems":[{"name":"Olja (1 tsk)","amount":5.0,"unit":"g"},{"name":"Kycklingbröstfilé","amount":140.0,"unit":"g"},{"name":"Ris, okokt (1 dl ca 80g)","amount":40.0,"unit":"g"},{"name":"Röd Paprika","amount":50.0,"unit":"g"},{"name":"Gul Paprika","amount":50.0,"unit":"g"},{"name":"Salladslök","amount":20.0,"unit":"g"},{"name":"Mini Fraiche, 5%","amount":75.0,"unit":"g"},{"name":"Grädde, 4%","amount":75.0,"unit":"g"},{"name":"Mango Chutney (2 msk); 1-2 tsk sambal oelek","amount":30.0,"unit":"g"}],"ingredients":"5g Olja (1 tsk)\n  140g Kycklingbröstfilé\n40g Ris, okokt (1 dl ca 80g)\n     50g Röd Paprika\n     50g Gul Paprika\n      20g Salladslök\n   75g Mini Fraiche, 5%\n      75g Grädde, 4%\n30g Mango Chutney (2 msk)\n   1-2 tsk sambal oelek","instructions":"1. Koka ris.\n  2. Stek kyckling  i olja och krydda\nmed paprikapulver, (cayennepeppar),\n      grillgrydda, salt & peppar.\n       3. Hacka upp din paprika.\n4. Blanda ihop grädde, creme fraiche,\nmango chutney, sambal oelek, salt &\n peppar (lite curry om du gillar det)\n    5. Lägg riset  i en form, på med\n    kyckling, paprika och såsen.\n6. In  i ugnen på 200 grader ca 20min.\n  7. Servera med valfria grönsaker!","image":"./ekefall-photos/ekefall-bok1-16.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-17","name":"Kyckling med brunsås","category":"Lunch","servings":1,"kcal":550,"protein":39,"carbs":63,"fat":14,"estimated":false,"ingredientItems":[{"name":"Kycklingbröstfilé","amount":140.0,"unit":"g"},{"name":"Potatis","amount":225.0,"unit":"g"},{"name":"Grädde, 10% (1 dl)","amount":100.0,"unit":"g"},{"name":"Mjölk (1 dl)","amount":100.0,"unit":"g"},{"name":"Gele (1 msk)","amount":15.0,"unit":"g"},{"name":"Sparris (ca 20g st); 1-2 tsk Fond; 1-2 tsk Soja","amount":80.0,"unit":"g"}],"ingredients":"140g Kycklingbröstfilé\n     225g Potatis\n100g Grädde, 10% (1 dl)\n   100g Mjölk (1 dl)\n    15g Gele (1 msk)\n 80g Sparris (ca 20g st)\n      1-2 tsk Fond\n       1-2 tsk Soja","instructions":"1. Koka upp potatis.\n   2. Skiva upp din kycklingfilé på\n   hälften och lägg  i en ugnsform.\n     3. Krydda med salt, peppar,\n    vitpeppar och paprikapulver.\n4. Häll på soja, fond & grädde sen in\ni ugnen på 175 grader ca 30 minuter.\n5. Mosa din potatis,  i med lite mjölk\n            i taget, salt och peppar.\n    6. Servera med sparris och en\n           klick gele! Njut!","image":"./ekefall-photos/ekefall-bok1-17.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-18","name":"Fajita kyckling","category":"Middag","servings":1,"kcal":550,"protein":37,"carbs":61,"fat":16,"estimated":false,"ingredientItems":[{"name":"Olivolja (1 tsk)","amount":5.0,"unit":"g"},{"name":"Kycklingbröstfilé","amount":125.0,"unit":"g"},{"name":"Libabröd (1 st)","amount":85.0,"unit":"g"},{"name":"Röd paprika","amount":40.0,"unit":"g"},{"name":"Gul paprika","amount":40.0,"unit":"g"},{"name":"Grön paprika","amount":40.0,"unit":"g"},{"name":"Röd lök","amount":40.0,"unit":"g"},{"name":"Lätt majonnäs","amount":25.0,"unit":"g"},{"name":"Grekisk youghurt, 0%","amount":25.0,"unit":"g"},{"name":"Vitlöksklyfta; 1-2 msk Fajita-mix","amount":1.0,"unit":"st"}],"ingredients":"5g Olivolja (1 tsk)\n  125g Kycklingbröstfilé\n   85g Libabröd (1 st)\n     40g Röd paprika\n     40g Gul paprika\n    40g Grön paprika\n       40g Röd lök\n    25g Lätt majonnäs\n25g Grekisk youghurt, 0%\n      1 Vitlöksklyfta\n    1-2 msk Fajita-mix","instructions":"1. Hacka upp paprika och lök.\n       2. Skär upp din kyckling.\n 3. Lägg allt på en plåt, krydda med\n din fajitakrydda eller tacokrydda.\n      4. Ringla över lite olivolja.\n5. Blanda ihop allt sen in  i ugnen 20-\n  25 minuter på 200 grader. Kolla\n kycklingen så den är klar innan du\n                 tar ut.\n  6. Gör en sås på grekisk yoghurt,\n majonnäs och vitlök, lite citron om\n      du vill + salt och peppar.\n   7. Lägg allt  i ditt bröd och njut!","image":"./ekefall-photos/ekefall-bok1-18.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-19","name":"Kebab-potatissallad","category":"Lunch","servings":1,"kcal":550,"protein":37,"carbs":54,"fat":21,"estimated":false,"ingredientItems":[{"name":"Olivolja (1 tsk)","amount":5.0,"unit":"g"},{"name":"Kycklingkebab","amount":140.0,"unit":"g"},{"name":"Potatis","amount":225.0,"unit":"g"},{"name":"Röd lök","amount":50.0,"unit":"g"},{"name":"Lätt Crème Fraiche,; Paprika & Chili","amount":75.0,"unit":"g"},{"name":"Grekisk youghurt, 0%; Lite persilja","amount":40.0,"unit":"g"}],"ingredients":"5g Olivolja (1 tsk)\n   140g Kycklingkebab\n      225g Potatis\n       50g Röd lök\n 75g Lätt Crème Fraiche,\n     Paprika & Chili\n40g Grekisk youghurt, 0%\n       Lite persilja","instructions":"1. Dela din potatis  i jämnstora bitar.\n    2. Krydda med salt, peppar &\n   paprikapulver, ringla över olja.\n  3. In  i ugnen på 200 grader, vänd\n    potatisen emellanåt så de inte\n    fastnar. Kolla var 10e minut.\n   4. När potatisen börjar bli klar\n   sätter du in din kycklingkebab.\n Den tar ca 10-15 min att bli klar.\n   5. Gör en sås på creme fraiche,\ngrekisk youghurt, rödlök & persilja.\n6. Rör ihop allt och njut! (Jag gillar\n den bäst kall men funkar att käka\n            direkt också)","image":"./ekefall-photos/ekefall-bok1-19.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-21","name":"Lövbiffsrullader","category":"Lunch","servings":1,"kcal":550,"protein":36,"carbs":57,"fat":20,"estimated":false,"ingredientItems":[{"name":"Olivolja (1 tsk)","amount":5.0,"unit":"g"},{"name":"Löfbiff","amount":120.0,"unit":"g"},{"name":"Potatis","amount":270.0,"unit":"g"},{"name":"Grädde, 10% (1 dl)","amount":100.0,"unit":"g"},{"name":"Färskost, Vitlök & Örter; Light, Philadelphia","amount":25.0,"unit":"g"},{"name":"sparris (ca 20g st)","amount":80.0,"unit":"g"},{"name":"soja","amount":1.0,"unit":"tsk"},{"name":"fond; Persilja att toppa med","amount":1.0,"unit":"tsk"}],"ingredients":"5g Olivolja (1 tsk)\n        120g Löfbiff\n       270g Potatis\n  100g Grädde, 10% (1 dl)\n25g Färskost, Vitlök & Örter\n     Light, Philadelphia\n   80g sparris (ca 20g st)\n          1 tsk soja\n          1 tsk fond\n    Persilja att toppa med","instructions":"1. Börja med att hacka upp potatis  i\n mindre bitar, salta, peppra och på\n           med olja.\n   2. In  i ugnen på 200 grader tills\n     potatisen har önskad yta.\n3. Bre din lövbiff med färskost, rulla\n      ihop sen salta & peppra.\n 4. Stek lövbiffen, när den börjar bli\nklar häller du  i grädde, fond & soja.\n 5. Servera med din potatis, sparris\n  och gärna lite extra valfri sallad\n                 6. Njut!","image":"./ekefall-photos/ekefall-bok1-21.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-22","name":"Falsk fläskfile","category":"Middag","servings":1,"kcal":550,"protein":31,"carbs":53,"fat":23,"estimated":false,"ingredientItems":[{"name":"Nötfärs (runt 12%)","amount":125.0,"unit":"g"},{"name":"Potatis","amount":250.0,"unit":"g"},{"name":"Grädde, 10% (1 dl)","amount":100.0,"unit":"g"},{"name":"Champinjoner","amount":40.0,"unit":"g"},{"name":"Smörgåsgurka","amount":20.0,"unit":"g"},{"name":"Lingonsylt (1 msk)","amount":15.0,"unit":"g"},{"name":"soja","amount":1.0,"unit":"tsk"},{"name":"fond; Persilja att toppa med","amount":1.0,"unit":"tsk"}],"ingredients":"125g Nötfärs (runt 12%)\n      250g Potatis\n100g Grädde, 10% (1 dl)\n   40g Champinjoner\n   20g Smörgåsgurka\n 15g Lingonsylt (1 msk)\n        1 tsk soja\n        1 tsk fond\n  Persilja att toppa med","instructions":"1. Krydda din färs med aromat.\n  2. Lägg ut plastfolie och rulla ihop\n din färs till en korv. in  i frysen 1-2\ntimmar. Ta ut & skiva upp färsen  i ca\n        1cm tjocka skivor.\n      3. Stek tills de fått fin yta.\n       4. Skiva upp champinjoner\n 5. Gör din sås på grädde, fond, soja,\n             salt & peppar.\n  6. Lägg ner din färs  i en form, på\n    med champinjoner + din sås.\n   7. In  i ugnen på 200 grader tills\n     champinjonerna mjuknat.\n    8. Servera med pressad potatis!","image":"./ekefall-photos/ekefall-bok1-22.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-23","name":"Ostburgare","category":"Lunch","servings":1,"kcal":550,"protein":41,"carbs":40,"fat":25,"estimated":false,"ingredientItems":[{"name":"Nötfärs (runt 12%)","amount":120.0,"unit":"g"},{"name":"Hamburgarbröd (1 st)","amount":70.0,"unit":"g"},{"name":"Burgar ost (2 st)","amount":40.0,"unit":"g"},{"name":"Ketschup (1 msk)","amount":15.0,"unit":"g"},{"name":"Lätt majonnäs (1 msk)","amount":15.0,"unit":"g"}],"ingredients":"120g Nötfärs (runt 12%)\n70g Hamburgarbröd (1 st)\n  40g Burgar ost (2 st)\n  15g Ketschup (1 msk)\n15g Lätt majonnäs (1 msk)","instructions":"1. Rulla färsen till 2 små bollar\n2. Tryck ut  i stekpannan, krydda med\n               salt, peppar.\n       3. Flippa och lägg på ost.\n 4. Rosta dina bröd, sätt sen ihop din\n    burgare (använd valfri mängd\n      grönsaker, ta vad du vill)\n\n\n           Enkelt & gott","image":"./ekefall-photos/ekefall-bok1-23.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-25","name":"Nötfärswok","category":"Lunch","servings":1,"kcal":550,"protein":34,"carbs":54,"fat":20,"estimated":false,"ingredientItems":[{"name":"Nötfärs (runt 12%)","amount":120.0,"unit":"g"},{"name":"Äggnudlar","amount":50.0,"unit":"g"},{"name":"Morötter","amount":50.0,"unit":"g"},{"name":"Rödkål, 50g Vitkål","amount":50.0,"unit":"g"},{"name":"Salladslök","amount":20.0,"unit":"g"},{"name":"Mini Fraiche (5%)","amount":50.0,"unit":"g"},{"name":"Siracha sås (2 tsk)","amount":10.0,"unit":"g"},{"name":"Sesamolja (1 tsk); 1-2 tsk ingefära; 1-2 Vitlöksklyftor; 1-2 tsk fond, 1-2 tsk soja","amount":5.0,"unit":"g"}],"ingredients":"120g Nötfärs (runt 12%)\n     50g Äggnudlar\n     50g Morötter\n 50g Rödkål, 50g Vitkål\n     20g Salladslök\n 50g Mini Fraiche (5%)\n 10g Siracha sås (2 tsk)\n  5g Sesamolja (1 tsk)\n     1-2 tsk ingefära\n   1-2 Vitlöksklyftor\n1-2 tsk fond, 1-2 tsk soja","instructions":"1. Börja med att steka på din färs,\n           press ner vitlök.\n2. Hacka upp vitkål,rödkål,morötter,\n   och ingefära, tillsätt  i pannan.\n 4. Sänk värmen, sätt på ett lock och\n    låt stå ettpar minuter tills allt\n             mjuknat.\n     5. Sen häller du  i fond, soja,\n     sesamolja, salt och peppar.\n  6. I med dina kokta nudlar och rör\n runt allt. Ta bort från plattan och\n          börja med såsen.\n  8. Blanda mini fraiche & siracha.\n 9. Toppa nu allt med salladslök och\n        din hemmagjorda sås!","image":"./ekefall-photos/ekefall-bok1-25.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-26","name":"Sushikebab","category":"Middag","servings":1,"kcal":550,"protein":37,"carbs":38,"fat":29,"estimated":false,"ingredientItems":[{"name":"Gyroskebab","amount":120.0,"unit":"g"},{"name":"Sarek, Polarbröd","amount":1.0,"unit":"st"},{"name":"Mager ost (ca 12% fett)","amount":30.0,"unit":"g"},{"name":"Pizzasås (mutti)","amount":50.0,"unit":"g"},{"name":"Röd lök","amount":30.0,"unit":"g"},{"name":"Het kebabsås (1 msk); schysstkäk","amount":15.0,"unit":"g"}],"ingredients":"120g Gyroskebab\n    1st Sarek, Polarbröd\n30g Mager ost (ca 12% fett)\n   50g Pizzasås (mutti)\n       30g Röd lök\n 15g Het kebabsås (1 msk)\n        schysstkäk","instructions":"1. Sätt ugnen på 200°C\n    2. Fördela tomatsås och ost\n        på ditt tunnbröd.\n      3. Stek kebaben och lägg\n        på ditt tunnbröd.\n        4. Rulla ihop sen in  i\n        ugnen ca 10 min.\n       5. Ta ut och skär upp  i\n         jämnstora bitar.\n6. Toppa med kebabsås och rödlök!","image":"./ekefall-photos/ekefall-bok1-26.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-28","name":"Köttfärsås med tortellini","category":"Middag","servings":1,"kcal":600,"protein":45,"carbs":47,"fat":25,"estimated":false,"ingredientItems":[{"name":"Nötfärs (runt 12%)","amount":100.0,"unit":"g"},{"name":"Tortellini (Rana)","amount":100.0,"unit":"g"},{"name":"Krossade tomater","amount":100.0,"unit":"g"},{"name":"Färskost light (11% fett)","amount":50.0,"unit":"g"},{"name":"Mager ost (ca 12% fett); 1-2 tsk fond; Små skillnader på Ranas; tortellini, jag använde; PROSCIUTTO CRUDO; DI PARMA","amount":25.0,"unit":"g"}],"ingredients":"100g Nötfärs (runt 12%)\n   100g Tortellini (Rana)\n   100g Krossade tomater\n50g Färskost light (11% fett)\n25g Mager ost (ca 12% fett)\n         1-2 tsk fond\n\n\n  Små skillnader på Ranas\n   tortellini, jag använde\n PROSCIUTTO CRUDO\n       DI PARMA","instructions":"1. Tillaga din tortellini.\n 2. Stek och krydda din färs (valfri\nkryddning), jag hade  i vitlökspulver,\n    grillkrydda, paprikapulver,\n             salt & peppar\n  3. I med färskost, fond, krossade\n     tomater och din tortellini.\n4. Lägg ner  i en form, toppa med ost\n   sen in  i ugnen tills osten smält.","image":"./ekefall-photos/ekefall-bok1-28.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-30","name":"Kebabspett","category":"Middag","servings":1,"kcal":550,"protein":37,"carbs":53,"fat":21,"estimated":false,"ingredientItems":[{"name":"Olivolja (1 tsk)","amount":5.0,"unit":"g"},{"name":"Nötfärs (runt 12%)","amount":120.0,"unit":"g"},{"name":"Potatis","amount":250.0,"unit":"g"},{"name":"Grekisk yoghurt (0% fett)","amount":50.0,"unit":"g"},{"name":"Ajvar","amount":50.0,"unit":"g"},{"name":"Parmesan (1 msk); 1-2 msk Persilja Servera med valfria grönsaker","amount":8.0,"unit":"g"}],"ingredients":"5g Olivolja (1 tsk)\n  120g Nötfärs (runt 12%)\n        250g Potatis\n50g Grekisk yoghurt (0% fett)\n         50g Ajvar\n    8g Parmesan (1 msk)\n       1-2 msk Persilja\n\n\nServera med valfria grönsaker","instructions":"1. Börja med att koka din potatis.\n   2. Blanda färsen med kebabkrydda.\n       3. Kläm färsen på dina spett.\n     4. Gör en enkel sås på Ajvar och\n)           grekisk yoghurt.\n    5. Nät potatisen är klar lägger du\n  dem på en form och pressar ner dem\n           med ett glas.\n    6. Ringla över lite olivolja sen in  i\n  ugnen på 200 grader ca 30 minuter.\n         7. Grilla/stek dina spett.\nr       8. Toppa sen din potatis med\n    parmesan, flingsalt och persilja!\n                  9. NJUT!","image":"./ekefall-photos/ekefall-bok1-30.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-31","name":"Tortillatårta","category":"Lunch","servings":1,"kcal":550,"protein":40,"carbs":56,"fat":18,"estimated":false,"ingredientItems":[{"name":"Skinka","amount":80.0,"unit":"g"},{"name":"Tortilla bröd (2 st)","amount":80.0,"unit":"g"},{"name":"Mager ost (ca 12%)","amount":50.0,"unit":"g"},{"name":"Kotivara Pepperonisalami","amount":20.0,"unit":"g"},{"name":"Pizzasås, mutti","amount":50.0,"unit":"g"},{"name":"Sweetchilisås (1 msk); Oregano","amount":15.0,"unit":"g"}],"ingredients":"80g Skinka\n   80g Tortilla bröd (2 st)\n   50g Mager ost (ca 12%)\n20g Kotivara Pepperonisalami\n     50g Pizzasås, mutti\n  15g Sweetchilisås (1 msk)\n         Oregano","instructions":"1. Börja med att fördela pizzasås &\n    sweet chilisås på dina bröd.\n   2. På med hälften av osten och\nskinka (eller kycklingpålägg/kalkon\n     om du har det hemma)\n       3. Rulla ihop och dela  i\n         jämnstora bitar.\n      4. Lägg ner  i en ugnsform\n    5. Toppa med resten av osten,\n       pepperoni & oregano.\n     6. In  i ugnen på 200 grader\n           ca 15-20 min.","image":"./ekefall-photos/ekefall-bok1-31.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-32","name":"Kålpudding i stekpanna","category":"Middag","servings":1,"kcal":550,"protein":35,"carbs":60,"fat":20,"estimated":false,"ingredientItems":[{"name":"Nötfärs (runt 12% fett)","amount":150.0,"unit":"g"},{"name":"Potatis","amount":150.0,"unit":"g"},{"name":"Vitkål","amount":150.0,"unit":"g"},{"name":"Gul lök","amount":30.0,"unit":"g"},{"name":"Grädde, 10-15% (1/2 dl)","amount":50.0,"unit":"g"},{"name":"Sirap (1 msk)","amount":15.0,"unit":"g"},{"name":"Inlagd gurka","amount":25.0,"unit":"g"},{"name":"Rårörda lingon (1 msk); 1-2 tsk fond; 1-2 tsk soja","amount":15.0,"unit":"g"},{"name":"vatten (ca)","amount":0.5,"unit":"dl"}],"ingredients":"150g Nötfärs (runt 12% fett)\n       150g Potatis\n        150g Vitkål\n        30g Gul lök\n50g Grädde, 10-15% (1/2 dl)\n     15g Sirap (1 msk)\n     25g Inlagd gurka\n 15g Rårörda lingon (1 msk)\n        1-2 tsk fond\n         1-2 tsk soja\n      1/2 dl vatten (ca)","instructions":"1. Koka potatis.\n2. Stek din köttfärs och hacka upp\n             kål & lök.\n   3. Häv ner  i pannan och stek\n            tills de mjuknat.\n     4. Tillsätt sirap, soja, salt.\n5. Låt steka ettpar minuter sen har\n  du  i fond och ca 1/2 dl vatten.\n6. På med ett lock och låt koka på\n       låg värme  i ca 20 min.\n     7. I med grädde och låt stå\n         ytterligare 10 min.\n  8. Servera med pressad potatis,\n  rårörda lingon & inlagd gurka.","image":"./ekefall-photos/ekefall-bok1-32.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-33","name":"Ostig Taco","category":"Lunch","servings":1,"kcal":550,"protein":39,"carbs":50,"fat":21,"estimated":false,"ingredientItems":[{"name":"Nötfärs (runt 12% fett)","amount":100.0,"unit":"g"},{"name":"Tortillabröd (2 st)","amount":80.0,"unit":"g"},{"name":"Ost (runt 17% fett)","amount":40.0,"unit":"g"},{"name":"rödlök","amount":30.0,"unit":"g"},{"name":"Jalapeños","amount":30.0,"unit":"g"},{"name":"Tacosås (2 msk)","amount":30.0,"unit":"g"},{"name":"Mini Fraiche, 5% (2 msk); 1-2 msk Tacokrydda","amount":30.0,"unit":"g"}],"ingredients":"100g Nötfärs (runt 12% fett)\n   80g Tortillabröd (2 st)\n   40g Ost (runt 17% fett)\n         30g rödlök\n       30g Jalapeños\n    30g Tacosås (2 msk)\n30g Mini Fraiche, 5% (2 msk)\n     1-2 msk Tacokrydda","instructions":"1. Stek och krydda din färs\n       med tacokrydda.\n2. Fram med dina tortillabröd, på\n   halva lägger du ost, färs lök,\n jalapeños & mer ost sen vik ihop.\n3. Stek någon minut på varje sida\neller in  i ugnen på 200 grader tills\n       brödet fått fin färg.\n4. Doppa  i tacosås & mini fraiche.","image":"./ekefall-photos/ekefall-bok1-33.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-34","name":"Lasagne i stekpanna","category":"Middag","servings":1,"kcal":550,"protein":38,"carbs":52,"fat":22,"estimated":false,"ingredientItems":[{"name":"Nötfärs (runt 12% fett)","amount":100.0,"unit":"g"},{"name":"Lasagneplattor","amount":50.0,"unit":"g"},{"name":"Krossade tomater","amount":100.0,"unit":"g"},{"name":"Mager ost (ca 12%)","amount":25.0,"unit":"g"},{"name":"Gul lök","amount":30.0,"unit":"g"},{"name":"Smör (2 tsk)","amount":10.0,"unit":"g"},{"name":"Mjöl (1 msk)","amount":9.0,"unit":"g"},{"name":"- 1dl Mjölk; 1-2 Vitlöksklyftor; 1-2 tsk Fond; Basilika att toppa med","amount":0.5,"unit":"st"}],"ingredients":"100g Nötfärs (runt 12% fett)\n    50g Lasagneplattor\n   100g Krossade tomater\n  25g Mager ost (ca 12%)\n        30g Gul lök\n     10g Smör (2 tsk)\n      9g Mjöl (1 msk)\n       1/2 - 1dl Mjölk\n     1-2 Vitlöksklyftor\n        1-2 tsk Fond\n   Basilika att toppa med","instructions":"1. Stek färs, lök och vitlök.\n    2.Krydda med salt & peppar.\n3. Tillsätt fond och krossade tomater\n      (kan behövas lita vatten)\n  4. Bryt lasagneplattor och tryck i,\nsätt på ett lock och låt stå ca 15 min.\n5. Gör en bechamelesås, smält smör  i\nen kastrull, tillsätt mjöl och rör runt.\n   6. Häll  i mjölken och rör runt på\n   medelvärme tills allt tjocknat.\n     7. Häll bechamelesåsen över\n             din köttfärs.\n    8. Toppa med ost (och basilika)\n             9. Smaklig spis!","image":"./ekefall-photos/ekefall-bok1-34.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-35","name":"Ihoprullad pizza","category":"Lunch","servings":1,"kcal":550,"protein":40,"carbs":47,"fat":21,"estimated":false,"ingredientItems":[{"name":"Pizzadeg (Pop bakery)","amount":100.0,"unit":"g"},{"name":"Pizzasås","amount":50.0,"unit":"g"},{"name":"Kycklingpålägg","amount":50.0,"unit":"g"},{"name":"Mager ost (ca 12% fett)","amount":50.0,"unit":"g"},{"name":"Kotivara Pepperonisalami; Oregano","amount":25.0,"unit":"g"}],"ingredients":"100g Pizzadeg (Pop bakery)\n        50g Pizzasås\n     50g Kycklingpålägg\n 50g Mager ost (ca 12% fett)\n25g Kotivara Pepperonisalami\n         Oregano","instructions":"1. Fram med din pizzadeg.\n   2. Fördela tomatsås på hälften.\n     3. Lägg på kycklingpålägg,\n           salami och ost.\n   4. Rulla ihop lite snyggt och nyp\n     degen, vänd sen på rullen.\n5. Vik in kanterna så inget rinner ut.\n     6. Gör små snitt  i degen & t\n        oppa med oregano.\n     7. In  i ugnen på 200 grader\n           ca 20 minuter.","image":"./ekefall-photos/ekefall-bok1-35.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-41","name":"Overnight oats med kanel","category":"Frukost","servings":1,"kcal":300,"protein":19,"carbs":40,"fat":8,"estimated":false,"ingredientItems":[{"name":"Kvarg, vanilj (1 dl)","amount":100.0,"unit":"g"},{"name":"Färskost light (2 msk)","amount":30.0,"unit":"g"},{"name":"Havregryn (1 dl)","amount":35.0,"unit":"g"},{"name":"Mjölk (2 msk)","amount":30.0,"unit":"g"},{"name":"Lönnsirap","amount":1.0,"unit":"msk"},{"name":"Sylt (valfri smak)","amount":1.0,"unit":"msk"}],"ingredients":"100g Kvarg, vanilj (1 dl)\n30g Färskost light (2 msk)\n   35g Havregryn (1 dl)\n   30g Mjölk (2 msk)\n     1 msk Lönnsirap\n 1 msk Sylt (valfri smak)","instructions":"1. Blanda kvarg, färskost, lönnsirap,\nmjölk och havregryn  i en skål/bunke.\n    2. Lägg sen  i en skål/matlåda\n       och toppa med kanel.\n  3. Sist lägger du på en klick sylt.\n4. Ät direkt eller låt stå över natten.","image":"./ekefall-photos/ekefall-bok1-41.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-42","name":"Äpplepaj","category":"Mellanmål","servings":1,"kcal":350,"protein":23,"carbs":47,"fat":9,"estimated":false,"ingredientItems":[{"name":"Äpple (1 st)","amount":1,"unit":"valfri mängd"},{"name":"Havregryn (2 msk)","amount":14.0,"unit":"g"},{"name":"Vetemjöl (1 msk)","amount":9.0,"unit":"g"},{"name":"Lönnsirap (1 tsk)","amount":7.0,"unit":"g"},{"name":"Smör (1 tsk)","amount":5.0,"unit":"g"},{"name":"Propud vanilj (1 paket); Kanel","amount":200.0,"unit":"g"}],"ingredients":"Äpple (1 st)\n   14g Havregryn (2 msk)\n    9g Vetemjöl (1 msk)\n    7g Lönnsirap (1 tsk)\n      5g Smör (1 tsk)\n200g Propud vanilj (1 paket)\n          Kanel","instructions":"1. Skiva upp ditt äpple tunt och\n  tillsätt kanel, lägg  i en skål/form\n          som tål ugn.\n     2. Rör ihop havregryn, mjöl,\n        lönnsirap och smör.\n      3. Lägg över dina äpplen.\n  4. Sätt in  i ugnen på 175 grader\n           ca 15 minuter.\n5. Toppa med din propud eller kvarg\n     om du har det hemma.","image":"./ekefall-photos/ekefall-bok1-42.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-43","name":"Bananpannkakor","category":"Frukost","servings":1,"kcal":350,"protein":23,"carbs":38,"fat":10,"estimated":false,"ingredientItems":[{"name":"Banan","amount":1.0,"unit":"st"},{"name":"Ägg","amount":1.0,"unit":"st"},{"name":"Smör (1 tsk)","amount":5.0,"unit":"g"},{"name":"Valfria bär","amount":50.0,"unit":"g"},{"name":"Lönnsirap (1 tsk)","amount":7.0,"unit":"g"},{"name":"Kvarg, vanilj (1,5 dl); Kanel","amount":150.0,"unit":"g"}],"ingredients":"1 Banan\n          1 Ägg\n     5g Smör (1 tsk)\n     50g Valfria bär\n   7g Lönnsirap (1 tsk)\n150g Kvarg, vanilj (1,5 dl)\n         Kanel","instructions":"1. Blanda ihop banan, en nypa salt\n        och kanel  i en skål.\n     2. Knäck  i 1 ägg och rör runt.\n 3. Värm upp en stekpanna med smör\n på medelhög värme. Tillsätt smeten\n(ca 2-3msk/pannkaka) och stek någon\n        minut på varje sida.\n  5. Servera pannkakorna och toppa\n  med vaniljkvarg, valfria bär och\n      lönnsirap. Smaklig måltid!\n\n\n     Riv över vit choklad om du\n              vill lyxa till det!","image":"./ekefall-photos/ekefall-bok1-43.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-44","name":"Mc’Toast","category":"Frukost","servings":1,"kcal":350,"protein":24,"carbs":30,"fat":11,"estimated":false,"ingredientItems":[{"name":"Hamburgerbröd","amount":1.0,"unit":"st"},{"name":"Skinka","amount":40.0,"unit":"g"},{"name":"Hamburger ost (2 skivor)","amount":40.0,"unit":"g"}],"ingredients":"1 Hamburgerbröd\n        40g Skinka\n40g Hamburger ost (2 skivor)","instructions":"1. Ta dina burgarbröd och\n        lägg upp och ner.\n2. På med ost och skinka sen sätt\n     ihop med fel sida “upp”\n 3. Stek  i torr panna, tryck ner\n med kastrull eller liknande så\n      mackan blir platt.\n               4. Njut!","image":"./ekefall-photos/ekefall-bok1-44.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-46","name":"Sandwich","category":"Mellanmål","servings":1,"kcal":300,"protein":9,"carbs":30,"fat":17,"estimated":false,"ingredientItems":[{"name":"Grekisk yoghurt (10%)","amount":50.0,"unit":"g"},{"name":"Färskost, light","amount":50.0,"unit":"g"},{"name":"Lönnsirap (1 tsk)","amount":7.0,"unit":"g"},{"name":"Mjölkchoklad","amount":20.0,"unit":"g"},{"name":"Göteborgs Kex Smörgåsrån (2 st)","amount":6.0,"unit":"g"},{"name":"skopa Proteinpulver (Helt valfritt); + ca 10g protein &; ca 60 kalorier","amount":0.5,"unit":"st"}],"ingredients":"50g Grekisk yoghurt (10%)\n     50g Färskost, light\n     7g Lönnsirap (1 tsk)\n      20g Mjölkchoklad\n6g Göteborgs Kex Smörgåsrån\n              (2 st)\n\n\n   1/2 skopa Proteinpulver\n        (Helt valfritt)\n    + ca 10g protein &\n        ca 60 kalorier","instructions":"1. Blanda Grekisk yoghurt, färskost,\n  lönnsirap, (proteinpulver om du vill)\n             och lite salt.\n            2. Smält chokladen.\n   3. Lägg dina kex  i en form, fördela\n         chokladen på kexen.\nn\n   4. Häll över “smeten” på ett av dina\n      kex sen lägg det andra på.\n  5. In  i frysen 2-3 timmar så har du en\n    supergod sandwich att njuta av!","image":"./ekefall-photos/ekefall-bok1-46.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok1-48","name":"Äpple med proteinglass","category":"Mellanmål","servings":1,"kcal":350,"protein":10,"carbs":58,"fat":9,"estimated":false,"ingredientItems":[{"name":"paket Dämn good, lohilo","amount":0.5,"unit":"st"},{"name":"Äpplen","amount":2.0,"unit":"st"},{"name":"Sirap; Kanel","amount":1.0,"unit":"msk"}],"ingredients":"1/2 paket Dämn good, lohilo\n          2 Äpplen\n         1 msk Sirap\n          Kanel","instructions":"1. Dela 2 äpplen på mitten och\n           ta ur kärnhuset.\n    2. På med kanel och hälften\n           av din sirap.\n    3. In  i airfryer eller ugn på\n        200 grader 15 min.\n   4. Toppa med ett halvt paket\nlohilo glass och resten av din sirap.","image":"./ekefall-photos/ekefall-bok1-48.jpg","source":"Anton Ekefäll – Topp 50 recept","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-01","name":"Allt i ett kyckling","category":"Lunch","servings":1,"kcal":550,"protein":39,"carbs":40,"fat":27,"estimated":false,"ingredientItems":[{"name":"Kycklinglår","amount":150.0,"unit":"g"},{"name":"Potatis","amount":175.0,"unit":"g"},{"name":"Grekisk Yoghurt (1 dl, 10% fett)","amount":100.0,"unit":"g"},{"name":"Gurka (ta mer om du vill)","amount":50.0,"unit":"g"},{"name":"Olivolja","amount":1.0,"unit":"Tsk"},{"name":"Tomatpure","amount":1.0,"unit":"Tsk"},{"name":"Honung; 1/2-1 Vitklöksklyfta; 1-2 Tsk Dill","amount":1.0,"unit":"Tsk"}],"ingredients":"150g Kycklinglår\n        175g Potatis\n   100g Grekisk Yoghurt\n        (1 dl, 10% fett)\n50g Gurka (ta mer om du vill)\n        1 Tsk Olivolja\n      1 Tsk Tomatpure\n        1 Tsk Honung\n     1/2-1 Vitklöksklyfta\n         1-2 Tsk Dill","instructions":"1. Börja med att hacka potatis  i\n mindre bitar, ner  i en form, på med\n        olja, salt, peppar & dill.\n     2. Ta fram en skål och blanda\n tomatpuré, honung, paprikapulver,\n chiliflakes, persilja, salt & peppar.\n3. Ner med din kyckling och rör runt,\n  lägg sen kycklingen på potatisen\n        (skinnet ner om du kör\n         kyckling med skinn)\n 4. In  i ugnen på 200 grader ca 45-60\n minuter, efter halva tiden så vänder\n         du på kycklingen.\n5. Servera med din tzatziki och njut!","image":"./ekefall-photos/ekefall-bok2-01.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-02","name":"Potatisgratäng med kebab","category":"Middag","servings":1,"kcal":600,"protein":41,"carbs":34,"fat":32,"estimated":false,"ingredientItems":[{"name":"Potatisgratäng (Peka)","amount":200.0,"unit":"g"},{"name":"Kycklingkebab (ca 5%)","amount":125.0,"unit":"g"},{"name":"Mager ost (ca 11%)","amount":50.0,"unit":"g"},{"name":"Lätt creme fraiche (1/2 dl) Jag tog den med smak av; paprika och chili. Valfri mängd grönsaker.","amount":50.0,"unit":"g"}],"ingredients":"200g Potatisgratäng (Peka)\n125g Kycklingkebab (ca 5%)\n  50g Mager ost (ca 11%)\n  50g Lätt creme fraiche\n           (1/2 dl)\n\n\n  Jag tog den med smak av\n     paprika och chili.\n\n\n  Valfri mängd grönsaker.","instructions":"1. Stek kebaben så den mjuknar.\n    2. Ta fram en form,  i med\n potatisgratäng, kycklingkebab,\n     creme fraiche och ost.\n3. Sätt in  i ugnen på 200 grader\n         ca 20 minuter.\n\n\n   Servera med en god sallad.","image":"./ekefall-photos/ekefall-bok2-02.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-03","name":"Smashed Caesar Taco","category":"Lunch","servings":1,"kcal":550,"protein":36,"carbs":43,"fat":27,"estimated":false,"ingredientItems":[{"name":"Kycklingfärs","amount":100.0,"unit":"g"},{"name":"Mini-Tortillas (3 st)","amount":75.0,"unit":"g"},{"name":"Bacon (2 skivor)","amount":40.0,"unit":"g"},{"name":"Salladsblad","amount":3.0,"unit":"st"},{"name":"Riven Parmesan","amount":1.0,"unit":"Msk"},{"name":"Caesardressing (Felix)","amount":2.0,"unit":"Msk"}],"ingredients":"100g Kycklingfärs\n  75g Mini-Tortillas (3 st)\n    40g Bacon (2 skivor)\n       3 st Salladsblad\n   1 Msk Riven Parmesan\n2 Msk Caesardressing (Felix)","instructions":"1. Tryck ut färsen på dina\n    mini-tortillas, salta & peppra.\n 2. Stek din bacon, sen sätt åt sidan.\n   3. I Samma panna steker du dina\n   mini-tortillas tills genomstekta,\n     flippa och stek någon minut\n          så brödet får färg.\n4. Toppa med sallad, riven parmesan,\n      caesardressing & bacon.","image":"./ekefall-photos/ekefall-bok2-03.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-04","name":"Max Chicken Parmesan","category":"Middag","servings":1,"kcal":550,"protein":36,"carbs":55,"fat":19,"estimated":false,"ingredientItems":[{"name":"Kycklingbröstfilé","amount":100.0,"unit":"g"},{"name":"Hamburgerbröd","amount":1.0,"unit":"st"},{"name":"Ost (ca 17%)","amount":30.0,"unit":"g"},{"name":"Vetemjöl","amount":1.0,"unit":"Tsk"},{"name":"Ägg","amount":1.0,"unit":"st"},{"name":"Cornflakes","amount":20.0,"unit":"g"},{"name":"Vitlökssås Valfri mängd grönsaker","amount":1.0,"unit":"Msk"}],"ingredients":"100g Kycklingbröstfilé\n   1 Hamburgerbröd\n   30g Ost (ca 17%)\n    1 Tsk Vetemjöl\n         1 Ägg\n    20g Cornflakes\n   1 Msk Vitlökssås\n\n\nValfri mängd grönsaker","instructions":"1. Börja med att skära din\n kycklingfile på hälften så den blir\n      tunnare. Salta & peppra.\n2. Krossa cornflakes och blanda med\n      parmesan, salt, peppar\n      & paprikavpulver.\n3. Vänd sen din kyckling  i mjöl, sen\n   ägg och sist cornflakesmixen.\n 4. In  i ugnen ca 20 minuter minuter\n  på 200 grader, efter halva tiden\n  vänder du på burgarna (tiden kan\n  variera något beroende på ugn)\n5. Rosta dina bröd sen tar du sallad,\n    lök, tomat, din burgare, ost &\n             vitklökssås.","image":"./ekefall-photos/ekefall-bok2-04.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-06","name":"Krämig Pasta Alfredo","category":"Middag","servings":1,"kcal":550,"protein":43,"carbs":48,"fat":20,"estimated":false,"ingredientItems":[{"name":"Kycklingbröstfilé","amount":125.0,"unit":"g"},{"name":"Pasta","amount":50.0,"unit":"g"},{"name":"Mjölk","amount":1.0,"unit":"dl"},{"name":"Ägg","amount":1.0,"unit":"st"},{"name":"Smör","amount":2.0,"unit":"Tsk"},{"name":"Mjöl (1 att vända kycklingen i; & 2 i såsen)","amount":3.0,"unit":"Tsk"},{"name":"Riven parmesan (1 att toppa med & 2 i såsen); Persilja att toppa med","amount":3.0,"unit":"Msk"}],"ingredients":"125g Kycklingbröstfilé\n         50g Pasta\n          1 dl Mjölk\n            1 Ägg\n         2 Tsk Smör\n         3 Tsk Mjöl\n  (1 att vända kycklingen  i\n      & 2  i såsen)\n   3 Msk Riven parmesan\n(1 att toppa med & 2  i såsen)\n    Persilja att toppa med","instructions":"1. Skär din kycklingfilé på hälften så\n  den blir tunnare. Vänd sen  i mjöl,\n ägg och sist panko (i panko-mixen\n     ska du ha  i paprikapulver,\n     vitlökspulver, salt & peppar)\n    2. In  i ugn eller airfryer på 200\n  grader ca 10-15 min (beror på hur\n         tjock kycklingen är)\n3. Smält smör,  i med mjöl och tillsätt\n    mjölk & kryddor. Chiliflakes,\n   persilja, oregano salt & peppar.\n   4. Riv  i parmesan & tillsätt din\n  kokta pasta. Toppa med persilja,\n  parmesan och din kyckling. Njut!","image":"./ekefall-photos/ekefall-bok2-06.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-07","name":"Kyckling i baconsås","category":"Lunch","servings":1,"kcal":550,"protein":39,"carbs":53,"fat":20,"estimated":false,"ingredientItems":[{"name":"Kycklingbröstfilé","amount":125.0,"unit":"g"},{"name":"Bacon (2 skivor)","amount":40.0,"unit":"g"},{"name":"Ris, okokt (1 dl = 80g)","amount":60.0,"unit":"g"},{"name":"Gul lök; 1-2 vitlöksklyftor","amount":30.0,"unit":"g"},{"name":"Matlagningsgrädde; 1/2-1 Tsk Dijonsenap; 1-2 Tsk Fond, 1-2 Tsk Soja","amount":0.5,"unit":"dl"},{"name":"Riven Parmesan; 1-2 Tsk Persilja","amount":1.0,"unit":"Tsk"}],"ingredients":"125g Kycklingbröstfilé\n   40g Bacon (2 skivor)\n60g Ris, okokt (1 dl = 80g)\n       30g Gul lök\n     1-2 vitlöksklyftor\n1/2 dl Matlagningsgrädde\n   1/2-1 Tsk Dijonsenap\n1-2 Tsk Fond, 1-2 Tsk Soja\n   1 Tsk Riven Parmesan\n     1-2 Tsk Persilja","instructions":"1. Börja med att steka bacon.\n 2. Hacka upp lök och skär kyckling\n                      i mindre bitar.\n  3. Sätt din bacon åt sida,  i samma\n   panna steker du vitlök, lök och\nkyckling. Krydda med salt & peppar.\n     4. Tillsätt fond, dijonsenap,\n           soja & grädde.\n5. Låt puttra några minuter, tillsätt\n        bacon och persilja.\n     6. Servera med ris och någon\n  god sallad, toppa med parmesan.","image":"./ekefall-photos/ekefall-bok2-07.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-08","name":"Ihoprullad kebab","category":"Middag","servings":1,"kcal":550,"protein":37,"carbs":51,"fat":22,"estimated":false,"ingredientItems":[{"name":"Pizzadeg (Pop bakery)","amount":100.0,"unit":"g"},{"name":"Pizzasås","amount":50.0,"unit":"g"},{"name":"Kycklingkebab","amount":75.0,"unit":"g"},{"name":"Mager ost (ca 12% fett)","amount":50.0,"unit":"g"},{"name":"Kebabsås (Schysst käk); Oregano; Fefferoni om du vill!","amount":1.0,"unit":"Msk"}],"ingredients":"100g Pizzadeg (Pop bakery)\n       50g Pizzasås\n    75g Kycklingkebab\n50g Mager ost (ca 12% fett)\n      1 Msk Kebabsås\n       (Schysst käk)\n        Oregano\n\n\n    Fefferoni om du vill!","instructions":"1. Fram med din pizzadeg.\n      2. Fördela tomatsås på lite\n         mer än hälften.\n         3. Lägg på din stekta\n      kycklingkebab och ost.\n 4. Rulla ihop lite snyggt, nyp degen\n       och vänd sen på rullen.\n5. Vik in kanterna så inget rinner ut.\n      6. Gör små snitt  i degen &\n        toppa med oregano.\n7. In  i ugnen på 200 grader ca 20-30\n minuter. (Kan behövas längre, kolla\n      så degen är klar  i mitten)","image":"./ekefall-photos/ekefall-bok2-08.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-09","name":"Kyckling i ugn","category":"Lunch","servings":1,"kcal":550,"protein":38,"carbs":60,"fat":17,"estimated":false,"ingredientItems":[{"name":"Kycklingbröstfilé","amount":150.0,"unit":"g"},{"name":"Ris (1 dl = ca 80g)","amount":60.0,"unit":"g"},{"name":"Matlagningsgrädde","amount":0.5,"unit":"dl"},{"name":"Lätt Creme fraiche","amount":0.5,"unit":"dl"},{"name":"Soja","amount":1.0,"unit":"Msk"},{"name":"Gelé Valfri mängd grönsaker!","amount":2.0,"unit":"Tsk"}],"ingredients":"150g Kycklingbröstfilé\n 60g Ris (1 dl = ca 80g)\n1/2 dl Matlagningsgrädde\n1/2 dl Lätt Creme fraiche\n       1 Msk Soja\n        2 Tsk Gelé\n\n\n Valfri mängd grönsaker!","instructions":"1. Börja med att lägga\n        kyckling  i en form.\n  2. Gör en sås på cremé fraiche,\n    grädde, soja, salt, peppar\n        & vitpeppar.\n 3. Häll över din kyckling sen in  i\nugnen ca 45 minuter på 175 grader.\n (Kolla kycklingen innan du tar ut)\n 4. Koka ris och hacka upp valfria\n   grönsaker medans kycklingen\n             är  i ugnen.\n5. Servera med en klick gelé. Njut!","image":"./ekefall-photos/ekefall-bok2-09.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-10","name":"Pesto-Pasta med kyckling","category":"Middag","servings":1,"kcal":550,"protein":35,"carbs":53,"fat":23,"estimated":false,"ingredientItems":[{"name":"Olja","amount":1.0,"unit":"Tsk"},{"name":"Kycklingbröstfilé","amount":125.0,"unit":"g"},{"name":"Pasta (1 dl = ca 35g)","amount":60.0,"unit":"g"},{"name":"Gul lök","amount":30.0,"unit":"g"},{"name":"Pesto","amount":1.0,"unit":"Msk"},{"name":"Matlagningsgrädde","amount":0.5,"unit":"dl"}],"ingredients":"1 Tsk Olja\n 125g Kycklingbröstfilé\n60g Pasta (1 dl = ca 35g)\n      30g Gul lök\n       1 Msk Pesto\n1/2 dl Matlagningsgrädde","instructions":"1. Koka pasta (spara lite\n            pastavatten)\n      2. Krydda din kyckling med\n  paprikapulver, grillkrydda, salt,\n  peppar och olja innan du steker.\n   3. När kycklingen är genomstekt\n        sätter du den åt sidan.\n  4. I samma panna fräser du på lök\n           sen  i med pesto.\n  5. Häll  i grädde & din kokta pasta\n   (smaka om det behövs mer salt)\n    6. Krydda med persilja & häll  i\npastavatten för rinnigare konsistens.\n          7. Servera och njut!","image":"./ekefall-photos/ekefall-bok2-10.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-11","name":"Crispy chicken taco","category":"Lunch","servings":1,"kcal":550,"protein":34,"carbs":68,"fat":14,"estimated":false,"ingredientItems":[{"name":"Kycklingfärs","amount":125.0,"unit":"g"},{"name":"Mini Tortillas","amount":3.0,"unit":"st"},{"name":"Cornflakes","amount":30.0,"unit":"g"},{"name":"Yellow Mustard","amount":1.0,"unit":"Tsk"},{"name":"Lätt majonnäs; Sallad; Lägg till andra grönsaker om du vill!","amount":1.0,"unit":"Msk"}],"ingredients":"125g Kycklingfärs\n     3st Mini Tortillas\n     30g Cornflakes\n  1 Tsk Yellow Mustard\n   1 Msk Lätt majonnäs\n         Sallad\n\n\nLägg till andra grönsaker\n      om du vill!","instructions":"1. Bland kycklingfärs, gul senap\n  (yellow mustard, finns att köpa på\n  Ica), paprikapulver, vitlökspulver,\n      lökpulver, salt & peppar.\n          2. Krossa cornflakes.\n  3. Forma kycklingen och tryck ut  i\n  mixen, tryck hårt så cornflakesen\n fastnar. (blöt händerna något så blir\n  det enklare att forma kycklingen)\n    4. In  i ugnen på en plåt  i ca 20\n minuter på 200 grader, efter halva\ntiden kan du vända (tiden kan variera\n      något beroende på ugn)\n  5. Toppa med sallad och lättmayo!","image":"./ekefall-photos/ekefall-bok2-11.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-12","name":"Kyckling-Burgare","category":"Middag","servings":1,"kcal":550,"protein":45,"carbs":40,"fat":24,"estimated":false,"ingredientItems":[{"name":"Kycklingfärs","amount":150.0,"unit":"g"},{"name":"Hamburgerbröd (ca 60g)","amount":1.0,"unit":"st"},{"name":"Cheddarost (ca 17% fett)","amount":30.0,"unit":"g"},{"name":"barbecuesås","amount":1.0,"unit":"Msk"},{"name":"Max-dressing (valfri sort); Sallad, rödlök + andra; grönsaker du gillar","amount":1.0,"unit":"Msk"}],"ingredients":"150g Kycklingfärs\n  1 Hamburgerbröd (ca 60g)\n30g Cheddarost (ca 17% fett)\n     1 Msk barbecuesås\n     1 Msk Max-dressing\n          (valfri sort)\n\n\n   Sallad, rödlök + andra\n     grönsaker du gillar","instructions":"1. Rulla två bollar av din\n            kycklingfärs.\n 2. Smasha ner  i en varm stekpanna,\n            salta & peppra.\n3. När burgaren är klar penslar du på\n   barbecuesås och lägger på ost.\n 4. Sätt ihop din burgare med valfria\n        grönsaker och njut!","image":"./ekefall-photos/ekefall-bok2-12.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-14","name":"Potatissallad med kebab","category":"Middag","servings":1,"kcal":550,"protein":32,"carbs":46,"fat":25,"estimated":false,"ingredientItems":[{"name":"Kycklingkebab (ca 5%)","amount":150.0,"unit":"g"},{"name":"Räfflade pommes (funkar med vanliga pommes; eller potatis också)","amount":125.0,"unit":"g"},{"name":"Lätt Creme Fraiche (Gärna någon med smak)","amount":100.0,"unit":"g"},{"name":"Gurka","amount":100.0,"unit":"g"},{"name":"Dill","amount":5.0,"unit":"g"},{"name":"Gräslök; Helt ok att ta extra gurka,; dill & gräslök.","amount":5.0,"unit":"g"}],"ingredients":"150g Kycklingkebab (ca 5%)\n   125g Räfflade pommes\n(funkar med vanliga pommes\n     eller potatis också)\n  100g Lätt Creme Fraiche\n  (Gärna någon med smak)\n        100g Gurka\n          5g Dill\n        5g Gräslök\n\n\n Helt ok att ta extra gurka,\n         dill & gräslök.","instructions":"1. Lägg din kyckling kebab och\n      pommes på på en plåt.\n     2. In  i ugnen på 200 grader\n     ca 20 min, pommesen kan\n        behöva lite längre.\n3. Hack upp gurka, dill och gräslök.\n  4. Lägg ner  i en skål tillsammans\n med creme fraiche, salt & peppar.\n  5. Tillsätt din potatis och kebab.\n\n\n                Njut!","image":"./ekefall-photos/ekefall-bok2-14.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-15","name":"Pesto-wrap","category":"Lunch","servings":1,"kcal":550,"protein":38,"carbs":60,"fat":16,"estimated":false,"ingredientItems":[{"name":"Grillad Kyckling (Tex den man köper på ica)","amount":100.0,"unit":"g"},{"name":"Libabröd","amount":1.0,"unit":"st"},{"name":"Pesto","amount":1.0,"unit":"Msk"},{"name":"Grekisk Yoghurt, 10%","amount":2.0,"unit":"Msk"},{"name":"Philadelphiaost (light, smak av vitlök & örter)","amount":3.0,"unit":"Msk"},{"name":"Honung; 1/2-1 Pressad Lime; Bladspenat","amount":1.0,"unit":"Tsk"}],"ingredients":"100g Grillad Kyckling\n (Tex den man köper på ica)\n          1 Libabröd\n         1 Msk Pesto\n 2 Msk Grekisk Yoghurt, 10%\n    3 Msk Philadelphiaost\n(light, smak av vitlök & örter)\n         1 Tsk Honung\n      1/2-1 Pressad Lime\n         Bladspenat","instructions":"1. Blanda ihop philadelphiaost,\n grekisk yoghurt, pesto, honung, lime,\n               salt & peppar.\n    2. Dela upp din kyckling  i mindre\n   bitar, jag körde på grillad kyckling\n     men funkar likabra med file.\n 3. Rör ihop allt, lägg på ditt libabröd\n       tillsammans med spenat.\n)  4. Rulla ihop, stek någon minut på\n  varje sida, sen är de bara att njuta!","image":"./ekefall-photos/ekefall-bok2-15.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-17","name":"Ost & Baconburgare","category":"Lunch","servings":1,"kcal":550,"protein":44,"carbs":33,"fat":28,"estimated":false,"ingredientItems":[{"name":"Nötfärs (ca 12%)","amount":120.0,"unit":"g"},{"name":"Hamburgarbröd (Ca 60-70g)","amount":1.0,"unit":"st"},{"name":"Ost (ca 17% fett)","amount":30.0,"unit":"g"},{"name":"Bacon (2 skivor)","amount":40.0,"unit":"g"},{"name":"Gul Lök; Andra valfria grönsaker om; du vill, picklad gurka är för; fint till också!","amount":30.0,"unit":"g"}],"ingredients":"120g Nötfärs (ca 12%)\n     1st Hamburgarbröd\n       (Ca 60-70g)\n   30g Ost (ca 17% fett)\n   40g Bacon (2 skivor)\n       30g Gul Lök\n\n\nAndra valfria grönsaker om\ndu vill, picklad gurka är för\n        fint till också!","instructions":"1. Hacka lök & rulla 2 små eller 1\n              lite större boll.\n2. Stek bacon, sätt åt sidan. Stek lök\n       i samma panna, sätt åt sidan.\n3. & sist smasha din burgare  i samma\n  panna, krydda med salt & peppar.\n           4. Lägg på din ost.\n5. Stek dina bröd  i en torr stekpanna\n och pressa ner dem, funkar utmärkt\n       att använda en kastrull.\n  6. Sätt ihop din burgare och njut!","image":"./ekefall-photos/ekefall-bok2-17.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-18","name":"Krämig Köttfärsås","category":"Middag","servings":1,"kcal":600,"protein":37,"carbs":53,"fat":27,"estimated":false,"ingredientItems":[{"name":"Smör","amount":1.0,"unit":"Tsk"},{"name":"Nötfärs (ca 12% fett)","amount":125.0,"unit":"g"},{"name":"Pasta","amount":60.0,"unit":"g"},{"name":"Gul Lök","amount":30.0,"unit":"g"},{"name":"Vitlöksklyfta","amount":1.0,"unit":"st"},{"name":"Matlagningsgrädde","amount":0.5,"unit":"dl"},{"name":"Parmesan","amount":1.0,"unit":"Msk"},{"name":"Tomatpuré","amount":1.0,"unit":"Msk"},{"name":"Fond","amount":1.0,"unit":"Tsk"}],"ingredients":"1 Tsk Smör\n125g Nötfärs (ca 12% fett)\n       60g Pasta\n       30g Gul Lök\n      1 Vitlöksklyfta\n 1/2 dl Matlagningsgrädde\n     1 Msk Parmesan\n     1 Msk Tomatpuré\n        1 Tsk Fond","instructions":"1. Stek lök & vitlök  i en klick\n     smör/olja tills de mjuknar.\n2. Tillsätt köttfärsen och krydda med\nbasilika, cayennepeppar, salt, peppar\n    + andra kryddor om du vill.\n    3. Tillsätt tomatpuré och fond.\n          Sist  i med grädde.\n   4. Ha  i din kokta pasta  i såsen,\n    toppa med parmesan och njut!\n\n\n  Om du vill kan du ha  i krossade\n tomater också, men jag tycker den\n            blir godare utan.","image":"./ekefall-photos/ekefall-bok2-18.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-19","name":"Chevapcici","category":"Lunch","servings":1,"kcal":550,"protein":33,"carbs":50,"fat":26,"estimated":false,"ingredientItems":[{"name":"Chevapcici (Ica)","amount":125.0,"unit":"g"},{"name":"Somunbröd (finns i; frysdisken på ica)","amount":65.0,"unit":"g"},{"name":"Lök","amount":30.0,"unit":"g"},{"name":"Ajvar","amount":50.0,"unit":"g"},{"name":"Grekisk Yoghurt, 10%; Funkar med lätt creme fraiche; också om du har det hemma!","amount":50.0,"unit":"g"}],"ingredients":"125g Chevapcici (Ica)\n   65g Somunbröd (finns  i\n      frysdisken på ica)\n          30g Lök\n         50g Ajvar\n  50g Grekisk Yoghurt, 10%\n\n\nFunkar med lätt creme fraiche\n också om du har det hemma!","instructions":"1. Börja med att grilla/steka\n              din cevapcici.\n     2. Värm ditt bröd  i mikro, ugn,\n                eller grillen.\n             3. Hacka upp lök.\n  4. Sen har du ajvar, grekisk yoghurt,\n  kött och lök  i ditt somunbröd. Njut!\n\n\n\ne","image":"./ekefall-photos/ekefall-bok2-19.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-20","name":"20 minuters Ramen","category":"Middag","servings":1,"kcal":600,"protein":34,"carbs":46,"fat":30,"estimated":false,"ingredientItems":[{"name":"Olja för stekning","amount":1.0,"unit":"tsk"},{"name":"Kött","amount":100.0,"unit":"g"},{"name":"Buldak Nudlar(1/2 paket)","amount":70.0,"unit":"g"},{"name":"Ägg","amount":1.0,"unit":"st"},{"name":"Lätt Majonnäs; Salladslök","amount":1.0,"unit":"Msk"},{"name":"Vitklöksklyfta; Ta ett kött du gillar! (kyckling/tofu funkar också)","amount":1.0,"unit":"st"}],"ingredients":"1 tsk Olja för stekning\n         100g Kött\n70g Buldak Nudlar(1/2 paket)\n            1 Ägg\n    1 Msk Lätt Majonnäs\n         Salladslök\n       1 Vitklöksklyfta\n\n\n    Ta ett kött du gillar!\n(kyckling/tofu funkar också)","instructions":"1. Koka dina nudlar ca 5 min, äggen\n  ca 6:30-7 min för något lös gula.\n 2. Blanda ihop såsen och kryddorna\n  från nudlarna, pressad vitklök &\n            majonnäs.\n3. Ta lite pastavatten  i din sås, börja\nmed 1/2 dl, om du vill ha en mer som\n   en soppa så tar du mer vatten.\n 4. Salta, peppra och stek ditt kött.\n5. Häv  i nudlarna  i såsen/soppan och\nrör runt. Toppa med dina ägghalvor,\n        kött och salladslök.\n\n\nObs. Såsen  i paketet är STARK, tar\n   du hela blir det extremt starkt.","image":"./ekefall-photos/ekefall-bok2-20.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-21","name":"Köttfärs i Somunbröd","category":"Lunch","servings":1,"kcal":550,"protein":31,"carbs":52,"fat":24,"estimated":false,"ingredientItems":[{"name":"Nötfärs (ca 12% fett)","amount":125.0,"unit":"g"},{"name":"Sweet chilisås","amount":1.0,"unit":"Msk"},{"name":"Somunbröd","amount":80.0,"unit":"g"},{"name":"Lätt Creme fraiche (1/2 dl)","amount":50.0,"unit":"g"},{"name":"Lätt majonnäs","amount":1.0,"unit":"Msk"},{"name":"vitlöksklyfta (ta mer/mindre om du vill) Servera gärna med mycket valfria grönsaker!","amount":1.0,"unit":"st"}],"ingredients":"125g Nötfärs (ca 12% fett)\n   1 Msk Sweet chilisås\n     80g Somunbröd\n 50g Lätt Creme fraiche\n          (1/2 dl)\n   1 Msk Lätt majonnäs\n      1 vitlöksklyfta\n(ta mer/mindre om du vill)\n\n\nServera gärna med mycket\n     valfria grönsaker!","instructions":"1. Börja med att steka din färs.\n2. Häll  i sweet chilisås och lite soja\n        + salt & peppar.\n3. Medans du steker färsen så sätter\n du in dina somunbröd  i ugn/mikro.\n  4. Hacka upp valfria grönsaker.\n   5. Gör en sås på crème fraiche,\n  majonnäs, vitlök, salt & peppar.","image":"./ekefall-photos/ekefall-bok2-21.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-22","name":"Chips-Taco","category":"Middag","servings":1,"kcal":550,"protein":29,"carbs":31,"fat":34,"estimated":false,"ingredientItems":[{"name":"Nötfärs (ca 12% fett)","amount":125.0,"unit":"g"},{"name":"Valfria chips (Eller byt ut mot 2x medium; tortillabröd för “vanlig” taco)","amount":50.0,"unit":"g"},{"name":"Nacho-cheese dipp","amount":2.0,"unit":"Msk"},{"name":"Lätt creme fraiche; Tacokrydda, så mycket/lite du; vill & valfria grönsaker.","amount":2.0,"unit":"Msk"}],"ingredients":"125g Nötfärs (ca 12% fett)\n      50g Valfria chips\n (Eller byt ut mot 2x medium\ntortillabröd för “vanlig” taco)\n   2 Msk Nacho-cheese dipp\n   2 Msk Lätt creme fraiche\n\n\nTacokrydda, så mycket/lite du\n    vill & valfria grönsaker.","instructions":"1. Köp dina favoritchips.\n     2. Klipp upp påsen och häll ut så\n        du har kvar ca 50g chips.\n        3. Stek och krydda din färs.\n)   4. Häv ner färsen över dina chips.\n    5. Varm din cheddardip (valfritt)\n              och häll på.\n      6. Toppa med valfria grönsaker\n           och creme fraiche!\nu","image":"./ekefall-photos/ekefall-bok2-22.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-23","name":"Korv med makaroner","category":"Lunch","servings":1,"kcal":550,"protein":35,"carbs":56,"fat":20,"estimated":false,"ingredientItems":[{"name":"Matkorv (maträtt)","amount":150.0,"unit":"g"},{"name":"Makaroner (1dl ca 35g)","amount":60.0,"unit":"g"},{"name":"Ketchup","amount":1.0,"unit":"Msk"},{"name":"Senap","amount":1.0,"unit":"Msk"},{"name":"Smör","amount":1.0,"unit":"Msk"}],"ingredients":"150g Matkorv (maträtt)\n60g Makaroner (1dl ca 35g)\n      1 Msk Ketchup\n       1 Msk Senap\n        1 Msk Smör","instructions":"1. Börja med att koka pasta.\n   2. Skär din korv  i mindre bitar\n        och stek sen  i smör.\n     3. Krydda valfritt, jag hade\n    paprikapulver, vitlökspulver,\n     grillkrydda, salt & peppar.\n 4. Servera med ketchup och senap.\n\n\n\n Tips. Stek  i hälften av smöret sen ta\n resten av smöret och rör ner  i dina\nmakaroner (efter du hällt av vattnet)","image":"./ekefall-photos/ekefall-bok2-23.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-24","name":"Lövbiffsgryta","category":"Middag","servings":1,"kcal":550,"protein":36,"carbs":64,"fat":19,"estimated":false,"ingredientItems":[{"name":"Olja","amount":1.0,"unit":"Tsk"},{"name":"Lövbiff","amount":125.0,"unit":"g"},{"name":"Ris (1 dl = ca 80g)","amount":60.0,"unit":"g"},{"name":"Matlagningsgrädde (3/4 dl)","amount":75.0,"unit":"ml"},{"name":"Tomatpuré","amount":1.0,"unit":"Msk"},{"name":"Gul lök; 1-2 Vitlöksklyftor","amount":30.0,"unit":"g"},{"name":"Soja","amount":2.0,"unit":"Tsk"},{"name":"Fond; 1-2 Tsk Persilja","amount":1.0,"unit":"Tsk"}],"ingredients":"1 Tsk Olja\n      125g Lövbiff\n 60g Ris (1 dl = ca 80g)\n75ml Matlagningsgrädde\n          (3/4 dl)\n    1 Msk Tomatpuré\n      30g Gul lök\n    1-2 Vitlöksklyftor\n        2 Tsk Soja\n       1 Tsk Fond\n     1-2 Tsk Persilja","instructions":"1. Börja med att fräsa på\n            lök & vitlök.\n 2. Sen har du  i köttet, krydda med\n   paprikapulver, vitpeppar, salt\n         & peppar.\n3. I med tomatpuré, fond och vatten.\n(Vatten så att köttet nästan täcks)\n  4. Låt puttra en stund (gärna 1-2\n      timmar om du har tid)\n  5. Sist häller du  i grädde, soja &\n persilja. Låt puttra några minuter.\n6. Servera med ris, någon god sallad\n         och en klick gelé.","image":"./ekefall-photos/ekefall-bok2-24.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-27","name":"Köttbullar & Potatismos","category":"Lunch","servings":1,"kcal":600,"protein":32,"carbs":54,"fat":29,"estimated":false,"ingredientItems":[{"name":"Smör","amount":2.0,"unit":"Tsk"},{"name":"Nötfärs (ca 12%)","amount":125.0,"unit":"g"},{"name":"Potatis","amount":200.0,"unit":"g"},{"name":"Gul lök","amount":30.0,"unit":"g"},{"name":"Inlagd Gurka","amount":30.0,"unit":"g"},{"name":"Lingonsylt","amount":1.0,"unit":"Msk"},{"name":"Matlagningsgrädde","amount":0.5,"unit":"dl"},{"name":"Mjölk","amount":0.5,"unit":"dl"},{"name":"Soja; 1/2-1 Tsk Fond","amount":1.0,"unit":"Tsk"}],"ingredients":"2 Tsk Smör\n 125g Nötfärs (ca 12%)\n      200g Potatis\n      30g Gul lök\n    30g Inlagd Gurka\n    1 Msk Lingonsylt\n1/2 dl Matlagningsgrädde\n       1/2 dl Mjölk\n        1 Tsk Soja\n     1/2-1 Tsk Fond","instructions":"1. Koka potatis och riv lök.\n    2. Blanda ner lök  i köttfärsen,\nkrydda med salt, peppar & vitpeppar.\n    3. Stek dina köttbullar  i smör.\n   4. Sätt åt sidan & använd samma\n  stekpanna för att göra brunsåsen.\n5. I med grädde, fond, soja, vitpeppar\n        (smaka av med salt)\n  6. Låt såsen sjuda några minuter.\n  7. Mosa din potatis. Salta, peppra\n  & häll  i lite mjölk  i taget tills du\n         får önskad konsistens\n         (helt ok att ta extra)\n      8. Sen är det bara att njuta!","image":"./ekefall-photos/ekefall-bok2-27.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-30","name":"Fläskfilé med bearnaise","category":"Middag","servings":1,"kcal":550,"protein":30,"carbs":37,"fat":33,"estimated":false,"ingredientItems":[{"name":"Olja","amount":2.0,"unit":"Tsk"},{"name":"Fläskfilé","amount":125.0,"unit":"g"},{"name":"Potatis","amount":200.0,"unit":"g"},{"name":"Bearnaisesås (Lohmanders, ska värmas); Som alltid helt ok att; lägga till grönsaker!","amount":3.0,"unit":"Msk"}],"ingredients":"2 Tsk Olja\n     125g Fläskfilé\n      200g Potatis\n   3 Msk Bearnaisesås\n(Lohmanders, ska värmas)\n\n\n Som alltid helt ok att\n  lägga till grönsaker!","instructions":"1. Hacka upp potatis  i mindre bitar.\n 2. På med olja sen in  i ugn/aifryer\n   ca 25 minuter på 200 grader.\n  3. Medans pommesen tillagas så\n     steker du din fläskfile och\n           värmer bea.\n 4. Salta dina pommes, servera med\n     din fläskfile och bea. Njut!","image":"./ekefall-photos/ekefall-bok2-30.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-31","name":"Riven Falukorv","category":"Lunch","servings":1,"kcal":550,"protein":30,"carbs":56,"fat":25,"estimated":false,"ingredientItems":[{"name":"Pasta (1 dl = ca 35g)","amount":50.0,"unit":"g"},{"name":"Falukorv","amount":100.0,"unit":"g"},{"name":"Mjölk Servera med valfria; grönsaker som alltid!","amount":3.0,"unit":"dl"}],"ingredients":"50g Pasta (1 dl = ca 35g)\n     100g Falukorv\n        3 dl Mjölk\n\n\n  Servera med valfria\n  grönsaker som alltid!","instructions":"1. Koka upp mjölk. Häv  i makaroner\n och rör runt med jämna mellanrum\n    så det ej fastnar (ca 20 min)\n2. Om du vill ha som bilden behöver\n du frysa din falukorv över natten\n  sen riva falukorven  i ett rivjärn.\n      Men funkar lika bra\n     att steka korven som vanligt.\n3. Salta och peppra dina makaroner,\n      ha  i muskot om du vill.\n         Servera och njut!","image":"./ekefall-photos/ekefall-bok2-31.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-37","name":"Blåbärs & Hallonsmoothie","category":"Frukost","servings":1,"kcal":350,"protein":24,"carbs":39,"fat":9,"estimated":false,"ingredientItems":[{"name":"Mjölk","amount":1.5,"unit":"dl"},{"name":"Yoghurt (runt 3% fett)","amount":1.5,"unit":"dl"},{"name":"Frysta Blåbär","amount":100.0,"unit":"g"},{"name":"Frysta Hallon","amount":100.0,"unit":"g"},{"name":"Proteinpulver (vanilj)","amount":0.5,"unit":"dl"},{"name":"Vaniljsocker","amount":2.0,"unit":"Tsk"}],"ingredients":"1.5 dl Mjölk\n1,5 dl Yoghurt (runt 3% fett)\n    100g Frysta Blåbär\n    100g Frysta Hallon\n     1/2 dl Proteinpulver\n            (vanilj)\n     2 Tsk Vaniljsocker","instructions":"1. Mixa och njut!\n\n\nHelt ok att ta extra bär/frukt\n    om du vill ha det i!","image":"./ekefall-photos/ekefall-bok2-37.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-39","name":"Shakshuka","category":"Frukost","servings":1,"kcal":400,"protein":19,"carbs":30,"fat":23,"estimated":false,"ingredientItems":[{"name":"Olja","amount":1.0,"unit":"Tsk"},{"name":"Ägg; 2-3 Tomater (eller 200g; krossade tomater)","amount":2.0,"unit":"st"},{"name":"Gul Lök","amount":0.5,"unit":"st"},{"name":"Lätt Creme Fraiche","amount":0.5,"unit":"dl"},{"name":"Bröd","amount":35.0,"unit":"g"}],"ingredients":"1 Tsk Olja\n           2 Ägg\n 2-3 Tomater (eller 200g\n    krossade tomater)\n       1/2 Gul Lök\n1/2 dl Lätt Creme Fraiche\n        35g Bröd","instructions":"1. Börja med att hacka tomat och lök\n                      i mindre bitar.\n 2. Stek löken  i en skvätt olja, vänd  i\n  tomat (funkar lika bra med 200g\n      krossade tomater istället)\n     3. Krydda med salt & peppar.\n    4. Låt sjuda under lock på låg\n       värme ca 10 minuter.\n5. Gör 2 gropar och knäck  i dina ägg.\n      6. Sätt på locket och låt stå\n         ytterligare 5-10 min.\n 7. Strö på lite flingsalt, servera med\n       bröd och cremé fraiche!\n    (Toppa gärna med koriander\n        om du gillar det)","image":"./ekefall-photos/ekefall-bok2-39.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-41","name":"Mannafrutti","category":"Mellanmål","servings":1,"kcal":400,"protein":41,"carbs":46,"fat":5,"estimated":false,"ingredientItems":[{"name":"Proteinmjölk (Arla med smak av Blåbär)","amount":2.5,"unit":"dl"},{"name":"Propud, vanilj","amount":250.0,"unit":"g"},{"name":"Mannagryn","amount":2.0,"unit":"Msk"},{"name":"Drottningsylt","amount":1.0,"unit":"Msk"}],"ingredients":"2,5 dl Proteinmjölk\n(Arla med smak av Blåbär)\n   250g Propud, vanilj\n     2 Msk Mannagryn\n   1 Msk Drottningsylt","instructions":"1. Värm upp din Proteinmjölk (Arla\n med smak av blåbär)  i en kastrull.\n 2. I med mannagryn och lite salt och\n    rör runt tills gröten tjocknat.\n   3. Sist  i med 250g Propud Vanilj.\n 4. Häll ner  i en skål/form, gör inget\nom den är rinnig, den stelnar  i kylen.\n      Låt stå över natten eller\n              tills den svalnat.\n   5. Toppa med Drottningsylt eller\n        annan sylt du gillar.\n\n\n       Funkar utmärkt med\n         vanlig mjölk också!","image":"./ekefall-photos/ekefall-bok2-41.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-45","name":"Våfflad/stekt Banan","category":"Mellanmål","servings":1,"kcal":350,"protein":12,"carbs":45,"fat":16,"estimated":false,"ingredientItems":[{"name":"Banan","amount":1.0,"unit":"st"},{"name":"Paket Lohilo glass","amount":0.5,"unit":"st"},{"name":"Smör","amount":1.0,"unit":"Tsk"},{"name":"Lönnsirap","amount":1.0,"unit":"Msk"}],"ingredients":"1 Banan\n1/2 Paket Lohilo glass\n      1 Tsk Smör\n   1 Msk Lönnsirap","instructions":"1. Stek din banan  i smör eller\n       lägg  i ditt våffeljärn.\n3. Kan behövas bakplåtspapper om\n du använder våffeljärn så bananen\n                ej fastnar.\n3. Toppa med 1/2 paket lohilo glass\n      & lönnsirap. Njut!","image":"./ekefall-photos/ekefall-bok2-45.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-48","name":"Frysta Vindruvor","category":"Mellanmål","servings":1,"kcal":200,"protein":1,"carbs":50,"fat":1,"estimated":false,"ingredientItems":[{"name":"Vindruvor; En skvätt pressad citron","amount":250.0,"unit":"g"},{"name":"socker; Du kan skippa både citron; och socker om du vill,; blir gott utan också!","amount":1.0,"unit":"Msk"}],"ingredients":"250g Vindruvor\n En skvätt pressad citron\n       1 Msk socker\n\n\nDu kan skippa både citron\n  och socker om du vill,\n    blir gott utan också!","instructions":"1. Lägg dina vindruvor  i en skål.\n       2. Pressa över citron.\n   3. Strö över socker/sötströ.\n4. Sätt in  i frysen några timmar,\n       gärna över natten.\n\n\n    Njut! Blir som piggelin!","image":"./ekefall-photos/ekefall-bok2-48.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."},{"id":"ekefall-bok2-49","name":"Melon-Snack","category":"Mellanmål","servings":1,"kcal":150,"protein":2,"carbs":34,"fat":0,"estimated":false,"ingredientItems":[{"name":"Fryst Vattenmelon","amount":250.0,"unit":"g"},{"name":"Honung; 1/2-1 Pressad Citron; Funkar lika bra med tex; jordgubbar eller några andra; bär du gillar.","amount":1.0,"unit":"Msk"}],"ingredients":"250g Fryst Vattenmelon\n       1 Msk Honung\n    1/2-1 Pressad Citron\n\n\n  Funkar lika bra med tex\njordgubbar eller några andra\n        bär du gillar.","instructions":"1. Enklaste receptet som finns.\n      Mixa allt och njut!\n\n\nOm den är svårmixad kan du hälla\n  i lite vatten, eller varför inte tex\n        fanta eller sprite!","image":"./ekefall-photos/ekefall-bok2-49.jpg","source":"Anton Ekefäll – Volym 2","nutritionNote":"Näringsvärden enligt receptboken, kan variera med varumärken och portionsändringar."}];
